class TestTheOperatorCli:
    def test_list_shows_the_built_ins(self, capsys) -> None:
        code = main(["--no-entry-points", "list"])
        printed = capsys.readouterr().out
        assert "astar@v1" in printed
        assert "dwa@v1" in printed
