def _record(
    self,
    started: float,
    encode_done: float,
    received: float,
    reported_compute_ms: float | None,
) -> None:
    end_to_end_ms = (received - started) * 1000.0
    encode_ms = (encode_done - started) * 1000.0
    # Transport is everything the host measured minus what the plugin
    # says it spent thinking. Clamped at zero rather than allowed
    # negative: a plugin reporting more compute than the whole round
    # trip took is reporting something impossible, and a negative
    # transport figure would launder that into a plausible number.
    transport_ms = encode_ms + max(
        0.0, end_to_end_ms - encode_ms - (reported_compute_ms or 0.0)
    )
    self.last_latency = LatencyBreakdown(
        transport_ms=transport_ms,
